import anthropic

client = anthropic.Anthropic()
MODEL = "claude-sonnet-4-5"
TOOLS = [
    {"name": "get_transaction", "description": "Look up a UPI transaction by its 12-digit UTR.",
     "input_schema": {"type": "object", "properties": {"utr": {"type": "string"}}, "required": ["utr"]}},
    {"name": "raise_dispute", "description": "Raise a dispute for a failed UPI debit. Needs human approval.",
     "input_schema": {"type": "object", "properties": {"utr": {"type": "string"}, "reason": {"type": "string"}},
                      "required": ["utr", "reason"]}},
]

def run_tool(name, args):
    if name == "get_transaction":
        return bank.transactions.get(args["utr"])
    if name == "raise_dispute":
        if not approvals.request(args["utr"], args["reason"]):     # a person decides
            return "Rejected by reviewer."
        return bank.disputes.create(args["utr"], args["reason"])
    return f"Unknown tool {name}"

def agent(question: str, max_steps: int = 8) -> str:
    messages = [{"role": "user", "content": question}]
    for _ in range(max_steps):                                     # step budget
        r = client.messages.create(model=MODEL, max_tokens=1024, system=SYSTEM,
                                   tools=TOOLS, messages=messages)
        messages.append({"role": "assistant", "content": r.content})
        if r.stop_reason != "tool_use":
            return "".join(b.text for b in r.content if b.type == "text")
        messages.append({"role": "user", "content": [
            {"type": "tool_result", "tool_use_id": b.id, "content": str(run_tool(b.name, b.input))}
            for b in r.content if b.type == "tool_use"]})
    raise RuntimeError("step budget exhausted")

