from agents import (Agent, GuardrailFunctionOutput, Runner, SQLiteSession,
                    function_tool, input_guardrail)

CARD = re.compile(r"\b(?:\d[ -]?){13,16}\b")

@function_tool
def get_transaction(utr: str) -> dict:
    """Look up a UPI transaction by its 12-digit UTR."""
    return bank.transactions.get(utr)

@function_tool
def raise_dispute(utr: str, reason: str) -> str:
    """Raise a dispute for a failed UPI debit. Needs human approval."""
    if not approvals.request(utr, reason):
        return "Rejected by reviewer."
    return bank.disputes.create(utr, reason)

@input_guardrail
async def no_card_numbers(ctx, agent, user_input) -> GuardrailFunctionOutput:
    found = bool(CARD.search(str(user_input)))
    return GuardrailFunctionOutput(output_info={"card": found}, tripwire_triggered=found)

