from google.adk.agents import Agent
from google.adk.runners import Runner
from google.adk.sessions import InMemorySessionService
from google.genai import types

def get_transaction(utr: str) -> dict:
    """Look up a UPI transaction by its 12-digit UTR."""
    return bank.transactions.get(utr)

def raise_dispute(utr: str, reason: str) -> dict:
    """Raise a dispute for a failed UPI debit. Needs human approval."""
    if not approvals.request(utr, reason):
        return {"status": "rejected"}
    return {"status": "raised", "reference": bank.disputes.create(utr, reason)}

agent = Agent(name="upi_disputes", model="gemini-flash-latest",
              instruction=SYSTEM, tools=[get_transaction, raise_dispute])

runner = Runner(agent=agent, app_name="support",
                session_service=InMemorySessionService())

async def ask(user_id: str, question: str):
    session = await runner.session_service.create_session(app_name="support", user_id=user_id)
    message = types.Content(role="user", parts=[types.Part(text=question)])
    async for event in runner.run_async(user_id=user_id, session_id=session.id,
                                        new_message=message):
        if event.is_final_response():
            return event.content.parts[0].text

