export async function POST(req: Request) {
  const { messages } = await req.json();
  const result = streamText({
    model: anthropic("claude-sonnet-4-5"),
    system: "You help customers with failed UPI payments.",
    messages,
    tools: {
      getTransaction: tool({
        description: "Look up a UPI transaction by UTR",
        inputSchema: z.object({ utr: z.string().regex(/^\d{12}$/) }),
        execute: async ({ utr }) => ({ utr, status: "debited_not_credited", amount: 2450 }),
      }),
    },
    stopWhen: stepCountIs(8),
  });
  return result.toUIMessageStreamResponse();
}

